        "text": "implicit casting",
        "refs": ["Q0010"],
        "claims": [
          {
            "text": "implicit casting happens whenever we're not going to lose data",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
