      "definition_text": {
        "text": "Implicit casting occurs automatically when converting a value to a type that can represent the value without loss of data, such as converting an integer to a double.",
        "refs": ["Q0010", "Q0011"],
        "claims": [
          {
            "text": "Implicit casting occurs automatically when converting a value to a type that can represent the value without loss of data, such as converting an integer to a double.",
            "basis": "direct_entailment",
