    },
    {
      "term": {
        "text": "explicit casting",
        "refs": ["Q0015", "Q0018"],
        "claims": [
          {
            "text": "Explicit casting is performed by the programmer to convert a value to a specific type, such as casting a double to an integer.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0015", "Q0018"],
            "related_refs": []
          }
        ]
      },
      "definition_text": {
        "text": "Explicit casting requires the programmer to specify the target type in parentheses before the value, e.g., (int) x, and is used when automatic conversion would lose data.",
        "refs": ["Q0015", "Q0016", "Q0018"],
        "claims": [
          {
            "text": "Explicit casting requires the programmer to specify the target type in parentheses before the value, e.g., (int) x, and is used when automatic conversion would lose data.",
            "basis": "direct_entailment",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "refs": ["Q0015", "Q0016", "Q0018"],
            "related_refs": []
          }
        ]
      },
      "context": null
    },
    {
      "term": {
        "text": "type compatibility for casting",
        "refs": ["Q0023", "Q0024"],
        "claims": [
          {
            "text": "Casting can only be performed between compatible primitive numeric types; non‑numeric types like strings cannot be directly cast to numbers.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0023", "Q0024"],
            "related_refs": []
          }
        ]
      },
      "definition_text": {
        "text": "Explicit casting is allowed only between compatible types, such as numeric primitives, and cannot be used to cast unrelated types like a string to an integer.",
